SELECT f.id, f.forward_frame_id, f.side, f.request_frame_id, f.origin_machine_id, f.origin_session_id, f.connection_id, f.expected_holder_machine_id, f.project_id, f.phase, CAST(f.deadline_at AS TEXT) AS deadline_at, CAST(f.created_at AS TEXT) AS created_at, CAST(f.updated_at AS TEXT) AS updated_at, origin.service_id AS origin_service_id, holder.service_id AS holder_service_id FROM machine_forward_requests f LEFT JOIN machine_enrollments origin ON origin.machine_id=f.origin_machine_id LEFT JOIN machine_enrollments holder ON holder.machine_id=f.expected_holder_machine_id WHERE f.side=? AND f.forward_frame_id=?;
